// Types are erased at runtime: data from outside must be checked by hand.
function isUser(x) {
  // A runtime guard, like a type predicate "x is User" in TypeScript
  return typeof x === "object" && x !== null &&
    typeof x.id === "number" && typeof x.name === "string";
}

function parseUser(text) {
  const data = JSON.parse(text); // unknown shape: could be anything
  if (!isUser(data)) throw new Error("bad user payload");
  return data;
}

const inputs = [
  '{"id": 1, "name": "Asha"}',
  '{"id": "1", "name": "Asha"}', // id is a string: a type annotation alone would not catch this
  'null',
];
for (const text of inputs) {
  try {
    console.log(text, "->", JSON.stringify(parseUser(text)));
  } catch (e) {
    console.log(text, "-> rejected:", e.message);
  }
}

// "unknown" idea: you must narrow a value before using it.
function describe(value) {
  // Each check narrows the value, like typeof narrowing in TypeScript
  if (typeof value === "string") return "string of length " + value.length;
  if (typeof value === "number") return "number, doubled is " + value * 2;
  if (Array.isArray(value)) return "array with " + value.length + " items";
  if (value === null) return "null";
  return "something else: " + typeof value;
}

const samples = ["hello", 21, [1, 2, 3], null, { a: 1 }, undefined];
for (const s of samples) {
  console.log(JSON.stringify(s), "=>", describe(s));
}

// Without narrowing (the "any" way) mistakes only show up at runtime:
try {
  const anything = 42;
  console.log(anything.toUpperCase());
} catch (e) {
  console.log("any-style bug:", e.message);
}

// Structural ("duck") typing: only the shape matters, not the declared class.
class Dog { constructor() { this.name = "Rex"; } speak() { return "woof"; } }
const robot = { name: "R2", speak() { return "beep"; }, battery: 90 }; // extra field is fine

function greet(animal) {
  // Works for anything that has name and speak()
  return animal.name + " says " + animal.speak();
}
console.log(greet(new Dog()));
console.log(greet(robot));

// Look-alike values mix freely, which is the downside of shapes:
const userId = "u-1";
const orderId = "o-9";
function findUser(id) { return "user " + id; }
console.log(findUser(orderId)); // wrong id kind, nothing complains

// A "brand" via a validating constructor makes the kinds distinct at runtime
function makeUserId(s) {
  if (!s.startsWith("u-")) throw new Error("not a user id: " + s);
  return s;
}
console.log(findUser(makeUserId(userId)));
try { makeUserId(orderId); } catch (e) { console.log(e.message); }

// Discriminated union: a shared "kind" field tells the shapes apart.
function area(shape) {
  switch (shape.kind) {
    case "circle": return Math.PI * shape.radius ** 2;
    case "rect": return shape.w * shape.h;
    default: throw new Error("unknown kind: " + shape.kind);
  }
}

// "in" narrowing: check for a property when there is no tag
function label(x) {
  if ("radius" in x) return "round thing";
  return "boxy thing";
}

// Truthiness narrowing also drops 0 and "" (a classic trap)
function show(n) {
  return n ? "got " + n : "nothing";
}

const shapes = [
  { kind: "circle", radius: 2 },
  { kind: "rect", w: 3, h: 4 },
];
for (const s of shapes) {
  console.log(s.kind, area(s).toFixed(2), label(s));
}
console.log(show(5), "|", show(0), "<- 0 was treated as missing");
console.log(show(undefined));

// assertNever: the runtime half of an exhaustiveness check.
function assertNever(x) {
  throw new Error("Unhandled case: " + JSON.stringify(x));
}

function handle(event) {
  switch (event.type) {
    case "login": return "welcome " + event.user;
    case "logout": return "bye " + event.user;
    // In TypeScript, event is 'never' here only if every case is handled above.
    default: return assertNever(event);
  }
}

const events = [
  { type: "login", user: "ann" },
  { type: "logout", user: "ann" },
  { type: "purchase", user: "ann" }, // a newer server sent a kind we do not know
];
for (const e of events) {
  try {
    console.log(handle(e));
  } catch (err) {
    console.log("error:", err.message);
  }
}

// Alternative: a handler table; missing keys are easy to detect
const handlers = { login: () => "in", logout: () => "out" };
console.log(Object.keys(handlers).join(","));

// "as const object" pattern: enum-like, iterable, and plain JavaScript.
const Role = Object.freeze({ Admin: "admin", Editor: "editor", Viewer: "viewer" });

// Dot access like an enum
console.log("Role.Admin =", Role.Admin);

// Iterable values (a TypeScript numeric enum would also yield names)
console.log("all roles:", Object.values(Role).join(", "));

// Runtime check that a string is a valid role
function isRole(s) {
  return Object.values(Role).includes(s);
}
console.log(isRole("editor"), isRole("root"));

// Frozen: changes are ignored, much like readonly
Role.Admin = "hacked";
console.log("after attempt:", Role.Admin);

// Reverse mapping that a numeric enum would create automatically
const Level = { Low: 0, High: 1 };
const reverse = {};
for (const [k, v] of Object.entries(Level)) reverse[v] = k;
console.log("reverse of 1:", reverse[1]);

// Validate LLM output at the trust boundary before using it.
// Schema: { action: "refund" | "ignore", amount: number >= 0 }
function validate(raw) {
  let data;
  try { data = JSON.parse(raw); } catch (e) { return { ok: false, error: "not JSON" }; }
  if (typeof data !== "object" || data === null) return { ok: false, error: "not an object" };
  if (data.action !== "refund" && data.action !== "ignore") {
    return { ok: false, error: "bad action" };
  }
  if (typeof data.amount !== "number" || !(data.amount >= 0)) {
    return { ok: false, error: "bad amount" };
  }
  return { ok: true, value: { action: data.action, amount: data.amount } };
}

const outputs = [
  '{"action":"refund","amount":12.5}',
  '{"action":"delete_all","amount":1}',
  '{"action":"refund","amount":"lots"}',
  'Sure! Here is the JSON: {...}',
];
for (const o of outputs) {
  const r = validate(o);
  console.log(o, "=>", r.ok ? "OK " + JSON.stringify(r.value) : "REJECT " + r.error);
}
